BEGIN;

INSERT INTO questions (section_id, topic, stem, choices, correct_index, explanation, difficulty, cognitive_level)
VALUES

-- Q1: medium / L2 — Clearly trivial misstatement threshold
(1, 'Misstatements and Control Deficiencies', 'During the audit of Meridian Logistics, the engagement team identifies a $200 pricing error in office supplies when overall materiality is set at $500,000. Under AU-C 450, the auditor should treat this misstatement as:', '["A factual misstatement requiring management correction", "A projected misstatement that must be extrapolated to the population", "Clearly trivial and not required to be accumulated on the summary of uncorrected misstatements", "A judgmental misstatement requiring further investigation"]'::jsonb, 2, 'AU-C 450.A2 defines clearly trivial as amounts well below materiality where accumulation would not be expected to affect the financial statements. At 0.04% of materiality, this $200 error is clearly trivial and need not be accumulated. Unlike a factual misstatement requiring correction, clearly trivial amounts fall below the threshold where accumulation serves a meaningful purpose.', 'medium', 2),

-- Q2: medium / L2 — Deficiency in design vs deficiency in operation
(1, 'Misstatements and Control Deficiencies', 'At Beacon Healthcare, the auditor finds that the company has a documented policy requiring supervisory review of all journal entries over $10,000, but the supervisor has not performed any reviews for the past six months. Under AU-C 265, this situation represents:', '["A deficiency in design because the control was never properly planned", "A deficiency in operation because the control exists but is not functioning as designed", "A material weakness because journal entries lack any oversight", "A significant deficiency only if the unreviewed entries contain errors"]'::jsonb, 1, 'AU-C 265.A1 distinguishes between design and operation deficiencies. A deficiency in operation exists when a properly designed control does not operate effectively or is not performed by a person with appropriate authority or competence. Here, the review policy is well-designed but simply not being executed. A design deficiency would exist if the control itself were missing or improperly structured rather than merely unenforced.', 'medium', 2),

-- Q3: easy / L1 — Adjusting entries vs reclassifying entries
(1, 'Misstatements and Control Deficiencies', 'What is the difference between an adjusting entry and a reclassifying entry identified during an audit?', '["An adjusting entry corrects a misstatement in financial statement amounts, while a reclassifying entry corrects a presentation or classification error", "An adjusting entry is proposed by management, while a reclassifying entry is proposed by the auditor", "An adjusting entry affects net income, while a reclassifying entry affects total assets", "An adjusting entry is always material, while a reclassifying entry is always immaterial"]'::jsonb, 0, 'AU-C 450.06 requires the auditor to accumulate misstatements, distinguishing between adjustments to amounts and reclassifications. Adjusting entries correct monetary errors in account balances affecting the trial balance, while reclassifying entries correct presentation or disclosure classification without changing net income or total assets. Unlike the claim that reclassifications only come from auditors, either party may identify classification errors.', 'easy', 1),

-- Q4: medium / L2 — Management representation about uncorrected misstatements
(1, 'Misstatements and Control Deficiencies', 'After completing fieldwork at Crestwood Manufacturing, the auditor requests that management include specific representations about uncorrected misstatements in the management representation letter. Under AU-C 580, management should represent that:', '["All identified misstatements have been corrected in the financial statements", "The auditor bears responsibility for the accuracy of any uncorrected misstatements", "No uncorrected misstatements exist because they were all adjusted", "The effects of uncorrected misstatements are immaterial, individually and in the aggregate, to the financial statements as a whole"]'::jsonb, 3, 'AU-C 580.16 requires the auditor to request management to provide a written representation that uncorrected misstatements are immaterial, individually and in the aggregate, to the financial statements. A summary of these items should be included in or attached to the representation letter. This differs from representing that all misstatements were corrected, since management may choose not to correct items deemed immaterial.', 'medium', 2),

-- Q5: easy / L1 — Tolerable misstatement definition
(1, 'Misstatements and Control Deficiencies', 'What is tolerable misstatement as used in the context of audit sampling?', '["The maximum amount of known misstatement the auditor will accept in a sample", "The aggregate of all projected misstatements found during the audit", "The application of performance materiality to a particular sampling procedure", "The threshold above which all misstatements must be reported to those charged with governance"]'::jsonb, 2, 'AU-C 530.A3 defines tolerable misstatement as the application of performance materiality to a particular audit sampling procedure. It represents the maximum misstatement in a population that the auditor is willing to accept for a particular class of transactions or account balance. Unlike the maximum known misstatement in a sample, tolerable misstatement relates to the entire population being tested.', 'easy', 1),

-- Q6: medium / L3 — Prior-year carryforward misstatement evaluation
(1, 'Misstatements and Control Deficiencies', 'Pinnacle Industries carried forward a $75,000 uncorrected revenue overstatement from Year 1 into Year 2. In Year 2, the auditor discovers a new $50,000 inventory understatement. When evaluating the cumulative effect on Year 2 financial statements, the auditor should:', '["Consider only the $50,000 current-year misstatement since the prior-year error was already evaluated", "Consider the cumulative $75,000 balance sheet effect of the prior-year misstatement along with the $50,000 current-year misstatement", "Ignore prior-year misstatements because they were below materiality when originally assessed", "Require management to restate Year 1 financial statements before evaluating Year 2"]'::jsonb, 1, 'AU-C 450.06 requires evaluation of uncorrected misstatements including those from prior periods whose effects persist in the current period. The auditor must assess the cumulative effect on current-period financial statements, considering both the ongoing balance sheet impact of the revenue overstatement and the new inventory understatement. Simply ignoring prior-year carryforward effects would understate the aggregate misstatement in the current year.', 'medium', 3),

-- Q7: medium / L2 — Repeat communication of prior-year significant deficiency
(1, 'Misstatements and Control Deficiencies', 'During the current-year audit of Alderton Services, the auditor notes that a significant deficiency in the payroll approval process, communicated in writing to governance last year, remains uncorrected. Under AU-C 265, the auditor should:', '["Communicate the significant deficiency again in writing to those charged with governance in the current year", "Rely on the prior-year communication and not repeat it unless the deficiency has worsened", "Downgrade the deficiency to a non-reportable condition since governance is already aware", "Communicate only verbally since the written notice was previously provided"]'::jsonb, 0, 'AU-C 265.12 requires the auditor to communicate significant deficiencies and material weaknesses in writing for each audit in which they are identified, even if previously communicated. Governance may change, and the continued existence of the deficiency is itself significant. Unlike relying on prior communications, each year''s audit stands independently, and repeated written communication reinforces the urgency of remediation.', 'medium', 2),

-- Q8: medium / L2 — Fraud-related factual misstatement classification
(1, 'Misstatements and Control Deficiencies', 'During the audit of Sterling Financial, the engagement team discovers that the accounts receivable manager intentionally recorded a fictitious $30,000 receivable to inflate quarterly revenue. When classifying this misstatement under AU-C 450, the auditor should treat it as:', '["A projected misstatement because the amount must be extrapolated", "A clearly trivial item if it falls below performance materiality", "A judgmental misstatement because it involves management discretion", "A factual misstatement arising from fraud that requires further consideration regardless of amount"]'::jsonb, 3, 'AU-C 450.A4 and AU-C 240 require that misstatements arising from fraud receive additional consideration beyond their monetary amount. A factual misstatement is one about which there is no doubt, and an intentionally fabricated receivable is factual and fraudulent. Unlike judgmental misstatements involving reasonable differences in estimates, fraud-related misstatements involve deliberate manipulation and cannot be treated as clearly trivial regardless of size.', 'medium', 2),

-- Q9: medium / L3 — Qualitative significance of debt covenant impact
(1, 'Misstatements and Control Deficiencies', 'Redstone Construction has a $90,000 uncorrected understatement of expenses that, if corrected, would cause the company to violate its bank loan covenant requiring a minimum current ratio of 2:1. The auditor sets overall materiality at $200,000. In this situation, the auditor should:', '["Disregard the covenant effect because the misstatement is below overall materiality", "Accept the misstatement as immaterial because it does not exceed the quantitative threshold", "Consider the qualitative significance of the misstatement because it could trigger a debt covenant violation", "Require management to renegotiate the loan covenant before issuing the audit report"]'::jsonb, 2, 'AU-C 450.11 requires the auditor to consider both quantitative and qualitative factors when evaluating uncorrected misstatements. Even though $90,000 is below the $200,000 materiality level, a covenant violation has significant qualitative implications for the entity''s financial position and going concern. Simply comparing the amount to quantitative materiality without considering the covenant impact would be an incomplete evaluation.', 'medium', 3),

-- Q10: easy / L1 — Clearly trivial meaning
(1, 'Misstatements and Control Deficiencies', 'What is the meaning of "clearly trivial" when applied to misstatements identified during an audit?', '["A misstatement that management has already corrected during the audit", "An amount well below materiality that would not affect financial statement users'' decisions", "Any misstatement under $1,000 regardless of the entity''s size", "A misstatement that the auditor chooses not to report to governance"]'::jsonb, 1, 'AU-C 450.A2 states that clearly trivial is not synonymous with "not material" but rather denotes an amount well below any reasonable materiality threshold. The auditor designates a threshold below which misstatements need not be accumulated because they are inconsequential. Unlike a fixed dollar threshold such as $1,000, clearly trivial is determined relative to the entity''s specific materiality level and circumstances.', 'easy', 1),

-- Q11: easy / L1 — Communication recipient for lesser deficiencies
(1, 'Misstatements and Control Deficiencies', 'What is the appropriate recipient for communication of control deficiencies that are not significant deficiencies or material weaknesses?', '["Management, communicated either in writing or verbally at the auditor''s discretion", "Those charged with governance in a formal written report", "Both management and those charged with governance in separate written communications", "The SEC and any applicable regulatory bodies"]'::jsonb, 0, 'AU-C 265.13 permits the auditor to communicate other control deficiencies to management at an appropriate level, either in writing or verbally. These lesser deficiencies do not require the formal written communication to governance that is mandated for significant deficiencies and material weaknesses. Unlike regulatory reporting, routine control deficiencies are communicated directly to management for operational improvement.', 'easy', 1),

-- Q12: hard / L4 — Subsequent discovery of fraud after report issuance
(1, 'Misstatements and Control Deficiencies', 'After issuing the audit report for Lakewood Pharmaceuticals on March 15, the auditor learns on April 2 that a material fraud was perpetrated through the override of segregation-of-duties controls throughout the audit period. The fraud was discovered by a new controller who started on March 20. The auditor should evaluate whether:', '["The subsequent discovery is irrelevant because the audit report was already issued", "The fraud should be disclosed in the next year''s audit as a prior-period adjustment", "The prior-year report should be reissued with an updated opinion date only", "The override constituted a material weakness that existed at the report date and consider the effect on the previously issued report under AU-C 560"]'::jsonb, 3, 'AU-C 560.14 requires the auditor to consider subsequently discovered facts that, had they been known at the report date, may have caused the auditor to revise the report. A material fraud through control override is a strong indicator of a material weakness that existed during the audit period. Unlike treating subsequent discoveries as irrelevant, the auditor must assess whether the previously issued opinion remains appropriate and take action as required.', 'hard', 4),

-- Q13: medium / L2 — Management override as material weakness indicator
(1, 'Misstatements and Control Deficiencies', 'During the audit of Thornhill Distribution, the CFO directed the accounting staff to record a $120,000 year-end adjustment without documentation or approval, bypassing the normal journal entry review process. Under AU-C 265, the auditor should evaluate this situation as:', '["A routine management adjustment that does not require further evaluation", "An indicator of a material weakness because management override of controls circumvents the control environment", "A deficiency in operation that is automatically classified as a significant deficiency", "A minor control deviation that requires only verbal communication to management"]'::jsonb, 1, 'AU-C 265.A12 identifies management override of internal controls as an indicator of a material weakness. When senior management bypasses established controls without documentation or approval, it undermines the entire control environment. Unlike a routine adjustment, undocumented overrides by the CFO suggest systemic risk that existing controls cannot prevent or detect material misstatement, warranting evaluation for material weakness.', 'medium', 2),

-- Q14: hard / L4 — Qualitative factors in evaluating multiple misstatements
(1, 'Misstatements and Control Deficiencies', 'Apex Financial Services has three uncorrected misstatements totaling $80,000 against an overall materiality of $250,000: a $40,000 revenue timing error, a $25,000 understatement of a legal liability under litigation, and a $15,000 overstatement of prepaid expenses. In evaluating whether these misstatements are material, the auditor determines that:', '["The $80,000 aggregate is below materiality, so no further evaluation is needed", "All three misstatements are clearly trivial and may be disregarded", "The litigation-related understatement warrants heightened qualitative scrutiny even though the aggregate is below quantitative materiality because it involves potential management bias", "Each misstatement should be evaluated independently without considering the aggregate effect"]'::jsonb, 2, 'AU-C 450.11 requires the auditor to evaluate uncorrected misstatements considering both quantitative amounts and qualitative factors such as management bias, sensitivity of disclosures, and the nature of items involved. The litigation liability understatement is particularly sensitive because it may reflect intentional underestimation. Unlike relying solely on the quantitative comparison to materiality, the auditor must assess whether management may be biased in areas involving significant judgment.', 'hard', 4),

-- Q15: easy / L1 — Deficiency in design definition
(1, 'Misstatements and Control Deficiencies', 'What is a deficiency in the design of an internal control under auditing standards?', '["A control that is too costly to implement effectively", "A control that operates inconsistently across different periods", "A control that was not performed by the appropriate personnel", "A control that is missing or not properly designed to prevent or detect misstatements on a timely basis"]'::jsonb, 3, 'AU-C 265.A1 defines a design deficiency as existing when a necessary control is missing or when an existing control is not properly designed so that, even if it operates as designed, the control objective would not be met. This differs from a deficiency in operation, where the control exists and is properly designed but is not performed consistently or by personnel with adequate authority or competence.', 'easy', 1),

-- Q16: medium / L3 — Pervasive misstatements and adverse opinion
(1, 'Misstatements and Control Deficiencies', 'The auditor of Cascade Enterprises identifies uncorrected misstatements totaling $175,000 against a materiality of $150,000. The misstatements are spread across revenue, inventory, and accounts payable, affecting all three primary financial statements. The auditor should consider issuing:', '["An adverse opinion because the misstatements are both material and pervasive across the financial statements", "A qualified opinion because the misstatements exceed materiality by only a small margin", "An unmodified opinion with an emphasis-of-matter paragraph about the misstatements", "A disclaimer of opinion because the auditor cannot determine the full extent of misstatements"]'::jsonb, 0, 'AU-C 705.08-.09 requires the auditor to consider both materiality and pervasiveness when determining the type of modified opinion. When uncorrected misstatements exceed materiality and affect multiple financial statement line items across different statements, the effects are pervasive. Unlike a qualified opinion addressing material but non-pervasive matters, an adverse opinion is appropriate when misstatements are both material and widespread throughout the financial statements.', 'medium', 3),

-- Q17: medium / L3 — Net vs gross misstatement evaluation
(1, 'Misstatements and Control Deficiencies', 'During the audit of Evergreen Retail, the auditor identifies a $60,000 overstatement in revenue and a $55,000 understatement in cost of goods sold. Management argues the net effect is only $5,000 and therefore immaterial. When evaluating these misstatements, the auditor should:', '["Accept management''s netting approach since the financial statement effect is minimal", "Report only the net $5,000 misstatement on the summary of uncorrected misstatements", "Consider each misstatement separately because netting could mask individually significant errors affecting different financial statement line items", "Average the two misstatements and compare the average to materiality"]'::jsonb, 2, 'AU-C 450.A16 cautions that offsetting misstatements in different accounts may mask individually significant errors. The $60,000 revenue overstatement and $55,000 cost of goods sold understatement each affect different assertions and line items. Unlike accepting a net approach, the auditor must evaluate whether the individual misstatements could influence users'' decisions about specific accounts, even when their aggregate net effect appears small.', 'medium', 3),

-- Q18: hard / L4 — Senior management fraud as material weakness indicator
(1, 'Misstatements and Control Deficiencies', 'During the audit of Pacific Coast Investments, the engagement team discovers that the CEO and VP of Finance colluded to overstate assets by $45,000 through fictitious intercompany transactions. Overall materiality is $300,000. Despite the small dollar amount, the auditor should evaluate this situation as:', '["A clearly trivial misstatement since it represents less than 15% of materiality", "A strong indicator of a material weakness because fraud involving senior management demonstrates a failure of the control environment regardless of dollar magnitude", "A significant deficiency that should be communicated in writing to the audit committee only", "A deficiency in operation requiring monitoring-level communication to management"]'::jsonb, 1, 'AU-C 265.A13 identifies fraud by senior management as a strong indicator of a material weakness, regardless of the amount involved. Collusion between the CEO and VP of Finance demonstrates a fundamental failure of tone at the top and the control environment. Unlike evaluating only the dollar magnitude, fraud by those who set the entity''s ethical standards creates a presumption that the control environment cannot prevent or detect material misstatements.', 'hard', 4),

-- Q19: easy / L1 — Summary of uncorrected misstatements purpose
(1, 'Misstatements and Control Deficiencies', 'What is the primary purpose of the auditor''s summary of uncorrected misstatements?', '["To document all identified misstatements for evaluation of their aggregate effect on the financial statements", "To provide management with a list of corrections required before the opinion is issued", "To create a legal record of management''s negligence in financial reporting", "To satisfy regulatory filing requirements for public companies"]'::jsonb, 0, 'AU-C 450.06 requires the auditor to accumulate misstatements identified during the audit, other than those that are clearly trivial. The summary serves as the basis for evaluating whether uncorrected misstatements are material, individually or in the aggregate. Unlike a required correction list, the summary is an evaluation tool that helps the auditor form a conclusion about the financial statements as a whole.', 'easy', 1),

-- Q20: easy / L1 — Timing of deficiency communication deadline
(1, 'Misstatements and Control Deficiencies', 'What is the deadline for written communication of significant deficiencies and material weaknesses under AU-C 265?', '["Within 30 days of discovering the deficiency", "Before the entity files its annual report with regulators", "Immediately upon identification during fieldwork", "No later than 60 days following the report release date"]'::jsonb, 3, 'AU-C 265.14 requires written communication of significant deficiencies and material weaknesses no later than 60 days following the report release date. This timeline allows the auditor to complete the evaluation of identified deficiencies before finalizing the communication. Unlike immediate notification during fieldwork, the 60-day window ensures all relevant deficiencies are assessed holistically before formal communication is issued.', 'easy', 1),

-- Q21: hard / L4 — Reversing prior-period misstatement effect on current income
(1, 'Misstatements and Control Deficiencies', 'The auditor of Ridgeway Electronics is evaluating the current-year financial statements and notes that a prior-year uncorrected $200,000 inventory overstatement has reversed into current-year cost of goods sold, improving current-year net income. Current-year materiality is $250,000. The auditor should:', '["Disregard the reversal since the misstatement was evaluated in the prior year", "Evaluate how the reversal affects current-year income and consider whether the correcting effect combined with any new misstatements causes a material misstatement of current-period results", "Accept the favorable impact because it reduces the risk of material misstatement in the current year", "Require a prior-period adjustment to eliminate the carryforward effect"]'::jsonb, 1, 'AU-C 450.10-.11 requires evaluation of prior-period uncorrected misstatements that affect current-period financial statements. A reversing overstatement that inflates current-year income creates a misstatement of current-period operating results even though it corrects the balance sheet. Unlike ignoring prior-year reversals, the auditor must consider how carryforward effects interact with new misstatements to determine the aggregate impact on the current year''s financial statements.', 'hard', 4),

-- Q22: medium / L3 — Governance communication cannot be restricted by chair
(1, 'Misstatements and Control Deficiencies', 'At Westfield Corporation, the auditor identifies a significant deficiency in the revenue recognition process. The audit committee chair asks the auditor to communicate the finding only to the CFO rather than to the full board. The auditor should:', '["Communicate the significant deficiency in writing to those charged with governance as required by AU-C 265, regardless of the audit committee chair''s request", "Follow the audit committee chair''s instruction since the chair speaks for governance", "Communicate only verbally to the CFO as directed by the governance representative", "Defer communication until the next audit cycle to allow time for remediation"]'::jsonb, 0, 'AU-C 265.11 requires written communication of significant deficiencies to those charged with governance. The auditor cannot limit required communications based on a single governance member''s preference. Significant deficiencies must reach all parties with oversight responsibility. Unlike following a single director''s instruction to limit distribution, the professional standard requires communication to the full governance body responsible for financial reporting oversight.', 'medium', 3),

-- Q23: hard / L3 — Restatement as material weakness indicator
(1, 'Misstatements and Control Deficiencies', 'Birchwood Financial restated its prior-year financial statements to correct a $1.2 million error in lease accounting under ASC 842. The error resulted from the controller''s misapplication of the standard rather than from a software limitation. When evaluating internal control, the auditor should classify this restatement as:', '["A deficiency in operation that does not affect the current year''s control assessment", "A minor accounting error that requires no classification as a control deficiency", "A significant deficiency that warrants only verbal communication to management", "An indicator of a material weakness because the restatement demonstrates that existing controls failed to prevent or detect a material misstatement"]'::jsonb, 3, 'AU-C 265.A14 identifies a restatement of previously issued financial statements to correct a material misstatement as a strong indicator of a material weakness. The restatement demonstrates that the entity''s controls over lease accounting were insufficient to prevent or detect a material error. Unlike classifying this as only a deficiency in operation, the actual occurrence of a material misstatement requiring restatement creates a presumption of material weakness.', 'hard', 3),

-- Q24: medium / L2 — Control deficiency in monitoring component
(1, 'Misstatements and Control Deficiencies', 'At Granite Peak Mining, the internal audit department has not performed any reviews of operating controls for over 18 months due to staffing shortages. External auditors discover multiple processing errors that the internal audit function would typically identify. Under AU-C 265, this lapse most likely represents:', '["An acceptable business decision based on resource constraints", "A scope limitation that prevents the auditor from issuing an opinion", "A deficiency in the monitoring component of internal control that may rise to significant deficiency or material weakness", "A deficiency that is clearly trivial because the processing errors were eventually found"]'::jsonb, 2, 'AU-C 265.A7 recognizes that deficiencies can exist within any component of internal control, including monitoring. The failure of internal audit to perform reviews for 18 months represents a breakdown in the entity''s monitoring activities, which are designed to assess whether controls are present and functioning. Unlike treating staffing shortages as an acceptable business decision, the auditor must evaluate whether the monitoring lapse enabled misstatements.', 'medium', 2),

-- Q25: hard / L4 — Missing control as design deficiency regardless of detected errors
(1, 'Misstatements and Control Deficiencies', 'While planning the audit of Copper Ridge Energy, the auditor determines that the company has no controls over the reconciliation of intercompany transactions, which total $8 million annually. No misstatements have been detected in preliminary testing. The auditor should classify this situation as:', '["At least a significant deficiency because a missing control represents a design deficiency that cannot be mitigated by the absence of detected misstatements", "Not a deficiency because no misstatements have actually occurred", "A deficiency in operation requiring only verbal communication to management", "Clearly trivial because preliminary testing has not revealed any errors"]'::jsonb, 0, 'AU-C 265.A1 and .A8 establish that a missing control is inherently a design deficiency. The severity assessment depends on the magnitude of potential misstatement and the likelihood that existing compensating controls would fail to prevent or detect errors. With $8 million in unreconciled intercompany transactions and no controls, the potential for material misstatement is significant. Unlike relying on the absence of detected errors, the auditor must evaluate the reasonable possibility of undetected misstatement.', 'hard', 4),

-- Q26: medium / L3 — Limitation statement in deficiency communication
(1, 'Misstatements and Control Deficiencies', 'After completing the audit of Summit Ridge Hotels, management asks the auditor to confirm in the deficiency communication letter that no other control deficiencies exist beyond those identified. The auditor should:', '["Include a confirmation statement as requested to provide management with assurance", "Decline and instead include a statement that the audit was not designed to identify all control deficiencies that might exist", "Expand audit procedures to identify all possible control deficiencies before issuing the letter", "Issue an adverse opinion on internal controls to avoid making an incomplete statement"]'::jsonb, 1, 'AU-C 265.A19 requires the communication to include a statement that the purpose of the audit was to express an opinion on the financial statements and not to identify all deficiencies in internal control. The auditor cannot provide negative assurance about the absence of other deficiencies. Unlike confirming that no other deficiencies exist, the standard explicitly limits expectations by noting the audit was not designed for comprehensive deficiency identification.', 'medium', 3),

-- Q27: medium / L3 — Disclosure omission as misstatement
(1, 'Misstatements and Control Deficiencies', 'During the audit of Valley Creek Enterprises, the auditor discovers that a required disclosure about a $2 million related-party transaction was omitted from the financial statement notes. Management argues this is not a misstatement because it does not affect account balances. The auditor should:', '["Accept management''s position because disclosures do not affect reported financial amounts", "Record the omission as a reclassifying entry on the summary of uncorrected misstatements", "Exclude the omission from the misstatement evaluation since it is qualitative in nature", "Treat the disclosure omission as a misstatement under AU-C 450 because misstatements include omissions in disclosures"]'::jsonb, 3, 'AU-C 450.04 defines misstatements broadly to include misstatements of amounts, classification, presentation, or disclosure. An omitted related-party disclosure is a misstatement that must be evaluated for materiality. Unlike limiting misstatements to account balance errors, the standard explicitly includes disclosure omissions, which can significantly affect users'' understanding of the financial statements and related-party relationships.', 'medium', 3),

-- Q28: medium / L2 — Known vs projected misstatements in sampling
(1, 'Misstatements and Control Deficiencies', 'During sample testing at Harborview Shipping, the auditor finds three errors totaling $12,000 in a sample of 40 invoices drawn from a population of 1,600 invoices. Under AU-C 450, the $12,000 represents the known misstatement, while the auditor must also consider:', '["The projected misstatement, which estimates the likely error in the untested population based on the sample results", "The tolerable misstatement, which represents the maximum error management will accept", "The clearly trivial threshold, which determines if the errors need to be accumulated", "The performance materiality, which is the amount set by the auditor to reduce sampling risk"]'::jsonb, 0, 'AU-C 450.05 and AU-C 530 require the auditor to project the misstatement found in a sample to the entire population. The $12,000 known misstatement found in 40 of 1,600 invoices must be extrapolated to estimate the likely total misstatement. Unlike tolerable misstatement, which is set before testing begins, the projected misstatement is calculated after testing by applying the error rate to the full population of untested items.', 'medium', 2),

-- Q29: easy / L2 — Written representation acknowledging immateriality
(1, 'Misstatements and Control Deficiencies', 'At Maple Grove Consulting, the auditor identifies $35,000 in uncorrected misstatements that management agrees are immaterial. Under AU-C 450, the auditor should request that management provide a written representation acknowledging:', '["That the auditor accepts responsibility for the uncorrected misstatements", "That the misstatements will be corrected in the subsequent period", "That the effects of the uncorrected misstatements are immaterial to the financial statements as a whole", "That the misstatements resulted from unintentional errors rather than fraud"]'::jsonb, 2, 'AU-C 450.12 requires the auditor to request a written representation from management that the effects of uncorrected misstatements are immaterial, individually and in the aggregate, to the financial statements. A summary of these items is included with or attached to the representation letter. Unlike requiring a commitment to correct in the next period, the representation confirms management''s assessment of immateriality for the current-period financial statements.', 'easy', 2),

-- Q30: easy / L1 — Control deficiency definition
(1, 'Misstatements and Control Deficiencies', 'What is a control deficiency in internal control under auditing standards?', '["A misstatement that the auditor discovers during substantive testing procedures", "A condition in which the design or operation of a control does not allow management or employees to prevent or detect misstatements on a timely basis", "A failure by management to file financial statements by the required deadline", "An intentional override of controls by senior management for operational purposes"]'::jsonb, 1, 'AU-C 265.07 defines a control deficiency as existing when the design or operation of a control does not allow management or employees, in the normal course of performing their assigned functions, to prevent or detect and correct misstatements on a timely basis. Unlike a discovered misstatement itself, a control deficiency refers to the underlying control weakness that may allow misstatements to occur or go undetected.', 'easy', 1)
;

COMMIT;
